/* =========================================================
   Glint Archive — Hugging Face orange theme
   ========================================================= */
:root {
    /* Orange palette (Hugging Face vibes) */
    --orange: #ff9d00;
    --orange-bright: #ffb340;
    --orange-deep: #ff6b00;
    --orange-dim: rgba(255, 157, 0, 0.14);
    --orange-glow: rgba(255, 157, 0, 0.35);

    /* Dark warm backgrounds */
    --bg-deepest: #16100a;
    --bg-deep: #1d1610;
    --bg-base: #241c14;
    --bg-raised: #2d2419;
    --bg-hover: #3a2e1f;
    --bg-active: #46371f;

    --border: rgba(255, 157, 0, 0.12);
    --border-strong: rgba(255, 157, 0, 0.3);

    --text-primary: #f5ede1;
    --text-secondary: #c9b99f;
    --text-muted: #8a7a60;

    --green: #57f287;
    --red: #ed4245;

    --radius: 10px;
    --radius-lg: 16px;

    --font: 'Inter', -apple-system, sans-serif;
    --font-mono: 'Fira Code', monospace;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
    height: 100%;
    overflow: hidden;
    font-family: var(--font);
    background: var(--bg-deepest);
    color: var(--text-primary);
}

body {
    display: flex;
    flex-direction: column;
}

/* ---------- Scrollbars ---------- */
.scrollbar-thin::-webkit-scrollbar { width: 8px; height: 8px; }
.scrollbar-thin::-webkit-scrollbar-track { background: transparent; }
.scrollbar-thin::-webkit-scrollbar-thumb {
    background: rgba(255, 157, 0, 0.25);
    border-radius: 4px;
}
.scrollbar-thin::-webkit-scrollbar-thumb:hover { background: rgba(255, 157, 0, 0.45); }

.hidden { display: none !important; }

/* =========================================================
   Top bar
   ========================================================= */
.topbar {
    display: flex;
    align-items: center;
    gap: 24px;
    padding: 0 20px;
    height: 58px;
    flex-shrink: 0;
    background: linear-gradient(180deg, #241a0e 0%, #1d1610 100%);
    border-bottom: 1px solid var(--border-strong);
    box-shadow: 0 2px 16px rgba(255, 107, 0, 0.08);
    z-index: 50;
}

.brand {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 19px;
    font-weight: 800;
    letter-spacing: -0.3px;
    white-space: nowrap;
}
.brand-emoji { font-size: 24px; filter: drop-shadow(0 0 8px var(--orange-glow)); }
.brand-accent {
    background: linear-gradient(90deg, var(--orange), var(--orange-deep));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.mode-tabs {
    display: flex;
    gap: 6px;
    background: var(--bg-deepest);
    padding: 5px;
    border-radius: 12px;
    border: 1px solid var(--border);
}

.mode-tab {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 18px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-secondary);
    font-family: var(--font);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.18s ease;
}
.mode-tab:hover { color: var(--text-primary); background: var(--bg-hover); }
.mode-tab.active {
    background: linear-gradient(135deg, var(--orange), var(--orange-deep));
    color: #1a1006;
    box-shadow: 0 2px 12px var(--orange-glow);
}

.topbar-stats {
    margin-left: auto;
    display: flex;
    gap: 8px;
    align-items: center;
}
.stat-pill {
    padding: 6px 12px;
    border-radius: 999px;
    background: var(--orange-dim);
    border: 1px solid var(--border);
    color: var(--orange-bright);
    font-size: 12.5px;
    font-weight: 600;
    white-space: nowrap;
}
.stat-link { text-decoration: none; transition: all 0.15s; }
.stat-link:hover { border-color: var(--orange); box-shadow: 0 0 10px var(--orange-glow); }

/* =========================================================
   Mode panels
   ========================================================= */
.mode-panel {
    display: none;
    flex: 1;
    min-height: 0;
}
.mode-panel.active { display: flex; }

/* =========================================================
   DISCORD MODE
   ========================================================= */
.discord-shell {
    display: flex;
    flex: 1;
    min-height: 0;
    width: 100%;
}

/* --- Server rail --- */
.server-bar {
    width: 72px;
    flex-shrink: 0;
    background: var(--bg-deepest);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 12px;
    gap: 8px;
}
.server-icon {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: var(--bg-raised);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: var(--text-secondary);
    font-size: 22px;
    transition: all 0.2s ease;
    position: relative;
}
.server-icon:hover { border-radius: 16px; background: var(--orange-deep); color: #fff; }
.server-icon.active {
    border-radius: 16px;
    background: linear-gradient(135deg, var(--orange), var(--orange-deep));
    color: #1a1006;
}
.server-icon.active::before {
    content: '';
    position: absolute;
    left: -12px;
    width: 4px;
    height: 36px;
    border-radius: 0 4px 4px 0;
    background: var(--orange-bright);
}
.guild-initials { font-weight: 800; font-size: 17px; }
.server-separator {
    width: 32px;
    height: 2px;
    background: var(--border-strong);
    border-radius: 1px;
    margin: 2px 0;
}

/* --- Channels sidebar --- */
.sidebar {
    width: 250px;
    flex-shrink: 0;
    background: var(--bg-deep);
    display: flex;
    flex-direction: column;
    border-right: 1px solid var(--border);
}
.sidebar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    border-bottom: 1px solid var(--border);
    box-shadow: 0 1px 4px rgba(0,0,0,0.3);
}
.server-name { font-size: 15.5px; font-weight: 700; }
.server-badge {
    font-size: 9.5px;
    font-weight: 800;
    letter-spacing: 0.8px;
    color: #1a1006;
    background: linear-gradient(135deg, var(--orange), var(--orange-deep));
    padding: 3px 7px;
    border-radius: 4px;
}

.channels-scroller {
    flex: 1;
    overflow-y: auto;
    padding: 12px 8px;
}

.channel-category {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 14px 8px 4px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    text-transform: uppercase;
    cursor: pointer;
    user-select: none;
}
.channel-category:hover { color: var(--orange-bright); }
.category-arrow { font-size: 8px; transition: transform 0.15s; }
.channel-category.collapsed .category-arrow { transform: rotate(-90deg); }

.channel-item {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 6px 10px;
    margin: 1px 0;
    border-radius: 6px;
    color: var(--text-secondary);
    font-size: 14.5px;
    cursor: pointer;
    transition: all 0.12s;
}
.channel-item:hover { background: var(--bg-hover); color: var(--text-primary); }
.channel-item.active {
    background: var(--orange-dim);
    color: var(--orange-bright);
    font-weight: 600;
}
.channel-item .hash { color: var(--text-muted); font-weight: 500; }
.channel-item.active .hash { color: var(--orange); }
.channel-item .ch-name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.channel-item .ch-count {
    font-size: 11px;
    color: var(--text-muted);
    background: var(--bg-deepest);
    padding: 1px 7px;
    border-radius: 999px;
}
.channel-item.active .ch-count { color: var(--orange-bright); }

.sidebar-footer {
    padding: 10px;
    background: var(--bg-deepest);
    border-top: 1px solid var(--border);
}
.user-area { display: flex; align-items: center; gap: 10px; }
.user-area-text { display: flex; flex-direction: column; }
.user-area-name { font-size: 13px; font-weight: 600; }
.user-area-sub { font-size: 11px; color: var(--text-muted); }

/* --- Chat pane --- */
.chat-pane {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    background: var(--bg-base);
}
.chat-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 13px 18px;
    border-bottom: 1px solid var(--border);
    box-shadow: 0 1px 4px rgba(0,0,0,0.25);
    flex-shrink: 0;
}
.channel-hash { font-size: 22px; color: var(--orange); font-weight: 600; }
.channel-title { font-size: 16px; font-weight: 700; }
.channel-count { font-size: 12.5px; color: var(--text-muted); margin-left: 8px; }

.messages-scroller {
    flex: 1;
    overflow-y: auto;
    padding: 16px 4px 24px;
}

.btn-more {
    display: block;
    margin: 8px auto 16px;
    padding: 8px 22px;
    border: 1px solid var(--border-strong);
    border-radius: 999px;
    background: var(--orange-dim);
    color: var(--orange-bright);
    font-family: var(--font);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
}
.btn-more:hover { background: var(--orange); color: #1a1006; box-shadow: 0 0 14px var(--orange-glow); }
.btn-more:disabled { opacity: 0.5; cursor: wait; }

/* --- Messages --- */
.msg-group {
    display: flex;
    gap: 14px;
    padding: 4px 18px;
    margin-top: 14px;
}
.msg-group:hover { background: rgba(255, 157, 0, 0.03); }
.msg-group.highlighted {
    background: var(--orange-dim);
    border-left: 3px solid var(--orange);
    animation: flash-target 1.6s ease;
}
@keyframes flash-target {
    0% { background: var(--orange-glow); }
    100% { background: var(--orange-dim); }
}

.avatar {
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 16px;
    color: #fff;
    background: hsl(var(--avatar-hue, 28), 65%, 45%);
    user-select: none;
}
.avatar-sm { width: 32px; height: 32px; font-size: 14px; }

.msg-body { flex: 1; min-width: 0; }
.msg-header { display: flex; align-items: baseline; gap: 8px; }
.msg-author { font-size: 15px; font-weight: 600; color: var(--orange-bright); }
.msg-time { font-size: 11.5px; color: var(--text-muted); }
.msg-content {
    font-size: 14.5px;
    line-height: 1.55;
    color: var(--text-primary);
    white-space: pre-wrap;
    word-break: break-word;
    margin-top: 1px;
}
.msg-content.followup { padding: 1px 0; }
.msg-content a { color: var(--orange-bright); }
.msg-content code {
    font-family: var(--font-mono);
    font-size: 13px;
    background: var(--bg-deepest);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 1px 5px;
}

.date-divider {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 22px 18px 6px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 600;
}
.date-divider::before, .date-divider::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--border);
}

/* --- Fake input bar --- */
.chat-input-bar { padding: 0 18px 20px; flex-shrink: 0; }
.fake-input {
    display: flex;
    align-items: center;
    gap: 12px;
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 11px 16px;
    cursor: not-allowed;
    opacity: 0.75;
}
.fake-input-plus {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--text-muted);
    color: var(--bg-deepest);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
}
.fake-input-text { color: var(--text-muted); font-size: 14px; }

/* --- Empty / loading states --- */
.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    gap: 8px;
    color: var(--text-muted);
    text-align: center;
    padding: 40px;
}
.empty-emoji { font-size: 48px; margin-bottom: 6px; }
.empty-state h3 { color: var(--text-secondary); font-size: 18px; }
.empty-state p { font-size: 14px; max-width: 360px; }

.loading-spinner {
    display: flex;
    justify-content: center;
    padding: 48px;
}
.spinner {
    width: 36px;
    height: 36px;
    border: 3px solid var(--orange-dim);
    border-top-color: var(--orange);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* =========================================================
   SEARCH MODE
   ========================================================= */
.search-shell {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    width: 100%;
    max-width: 980px;
    margin: 0 auto;
    padding: 26px 24px 0;
}

.search-controls { flex-shrink: 0; }
.search-title { font-size: 26px; font-weight: 800; }
.search-sub { color: var(--text-muted); font-size: 14px; margin: 4px 0 18px; }

.search-row { display: flex; gap: 12px; }

.user-select {
    background: var(--bg-raised);
    border: 1px solid var(--border-strong);
    border-radius: var(--radius);
    color: var(--text-primary);
    font-family: var(--font);
    font-size: 14.5px;
    font-weight: 500;
    padding: 12px 14px;
    cursor: pointer;
    max-width: 260px;
    transition: border-color 0.15s;
}
.user-select:hover, .user-select:focus { border-color: var(--orange); outline: none; }
.user-select-lg { width: 100%; max-width: 420px; font-size: 16px; }

.search-input-wrap { position: relative; flex: 1; display: flex; align-items: center; }
.search-input-icon {
    position: absolute;
    left: 14px;
    color: var(--text-muted);
    pointer-events: none;
}
.search-input {
    width: 100%;
    background: var(--bg-raised);
    border: 1px solid var(--border-strong);
    border-radius: var(--radius);
    color: var(--text-primary);
    font-family: var(--font);
    font-size: 16px;
    padding: 12px 44px;
    transition: all 0.15s;
}
.search-input:focus {
    outline: none;
    border-color: var(--orange);
    box-shadow: 0 0 0 3px var(--orange-dim), 0 0 18px var(--orange-glow);
}
.search-input::placeholder { color: var(--text-muted); }

.search-live-dot {
    position: absolute;
    right: 16px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--text-muted);
    opacity: 0.4;
    transition: all 0.2s;
}
.search-live-dot.live {
    background: var(--orange);
    opacity: 1;
    box-shadow: 0 0 10px var(--orange-glow);
    animation: pulse 1s ease infinite;
}
@keyframes pulse {
    50% { transform: scale(1.35); }
}

.search-meta {
    margin: 12px 2px 10px;
    font-size: 13.5px;
    color: var(--text-muted);
    font-weight: 500;
}
.search-meta .match-count { color: var(--orange-bright); font-weight: 700; }

.search-results {
    flex: 1;
    overflow-y: auto;
    min-height: 0;
    padding-bottom: 12px;
}

.result-card {
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 13px 16px;
    margin-bottom: 10px;
    cursor: pointer;
    transition: all 0.15s;
    animation: slide-in 0.25s ease both;
}
@keyframes slide-in {
    from { opacity: 0; transform: translateY(6px); }
}
.result-card:hover {
    border-color: var(--orange);
    box-shadow: 0 2px 14px rgba(255, 107, 0, 0.15);
    transform: translateY(-1px);
}
.result-meta {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 6px;
    font-size: 12.5px;
}
.result-author { color: var(--orange-bright); font-weight: 700; font-size: 13.5px; }
.result-channel {
    color: var(--text-secondary);
    background: var(--bg-deepest);
    padding: 2px 8px;
    border-radius: 999px;
    font-weight: 500;
}
.result-time { color: var(--text-muted); margin-left: auto; }
.result-content {
    font-size: 14px;
    line-height: 1.5;
    color: var(--text-primary);
    word-break: break-word;
    white-space: pre-wrap;
}
.result-jump {
    margin-top: 8px;
    font-size: 12px;
    color: var(--text-muted);
}
.result-card:hover .result-jump { color: var(--orange); }

mark {
    background: var(--orange);
    color: #1a1006;
    font-weight: 700;
    border-radius: 3px;
    padding: 0 2px;
    box-shadow: 0 0 8px var(--orange-glow);
}

.search-more-wrap { flex-shrink: 0; padding: 6px 0 16px; text-align: center; }

/* =========================================================
   FUN FACTS MODE
   ========================================================= */
.facts-shell {
    flex: 1;
    overflow-y: auto;
    width: 100%;
    padding: 26px 24px 48px;
}
.facts-controls {
    max-width: 1100px;
    margin: 0 auto 24px;
}
.facts-title { font-size: 26px; font-weight: 800; }
.facts-sub { color: var(--text-muted); font-size: 14px; margin: 4px 0 16px; }

#facts-content { max-width: 1100px; margin: 0 auto; }

.facts-hero {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
    margin-bottom: 18px;
}
.hero-stat {
    background: linear-gradient(135deg, var(--bg-raised), var(--bg-base));
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 16px;
    text-align: center;
    transition: all 0.2s;
}
.hero-stat:hover { border-color: var(--orange); transform: translateY(-2px); }
.hero-stat-value {
    font-size: 26px;
    font-weight: 800;
    background: linear-gradient(90deg, var(--orange-bright), var(--orange-deep));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1.2;
    word-break: break-word;
}
.hero-stat-label {
    font-size: 11.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--text-muted);
    margin-top: 6px;
}

.facts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 16px;
}

.fact-card {
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 18px;
    animation: slide-in 0.3s ease both;
}
.fact-card-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 14px;
    color: var(--orange-bright);
}
.fact-card-title .fact-emoji { font-size: 18px; }

.bar-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}
.bar-label {
    width: 130px;
    flex-shrink: 0;
    font-size: 13px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: right;
    font-family: var(--font-mono);
}
.bar-track {
    flex: 1;
    height: 18px;
    background: var(--bg-deepest);
    border-radius: 4px;
    overflow: hidden;
}
.bar-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--orange-deep), var(--orange));
    border-radius: 4px;
    transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
    box-shadow: 0 0 8px rgba(255, 107, 0, 0.3);
}
.bar-count {
    width: 52px;
    flex-shrink: 0;
    font-size: 12px;
    color: var(--text-muted);
    font-family: var(--font-mono);
}

.fact-blockquote {
    background: var(--bg-deepest);
    border-left: 3px solid var(--orange);
    border-radius: 6px;
    padding: 12px 14px;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--text-secondary);
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 180px;
    overflow-y: auto;
}

.hour-chart {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    height: 90px;
    margin-top: 6px;
}
.hour-bar-wrap {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    height: 100%;
    justify-content: flex-end;
}
.hour-bar {
    width: 100%;
    background: linear-gradient(180deg, var(--orange), var(--orange-deep));
    border-radius: 3px 3px 0 0;
    min-height: 2px;
    transition: height 0.5s ease;
    opacity: 0.85;
}
.hour-bar-wrap:hover .hour-bar { opacity: 1; box-shadow: 0 0 8px var(--orange-glow); }
.hour-bar-wrap.peak .hour-bar { background: var(--orange-bright); opacity: 1; }
.hour-label { font-size: 8.5px; color: var(--text-muted); font-family: var(--font-mono); }

.fact-card.wide { grid-column: 1 / -1; }

/* =========================================================
   Responsive
   ========================================================= */
@media (max-width: 900px) {
    .topbar { gap: 12px; padding: 0 12px; }
    .topbar-stats { display: none; }
    .mode-tab { padding: 8px 12px; font-size: 13px; }
    .server-bar { display: none; }
    .sidebar { width: 200px; }
    .bar-label { width: 90px; }
}
@media (max-width: 640px) {
    .brand-name { display: none; }
    .sidebar { width: 160px; }
    .search-row { flex-direction: column; }
    .user-select { max-width: none; }
}

toolUseResult.content:
/* =========================================================
   Glint Archive — Hugging Face orange theme
   ========================================================= */
:root {
    /* Orange palette (Hugging Face vibes) */
    --orange: #ff9d00;
    --orange-bright: #ffb340;
    --orange-deep: #ff6b00;
    --orange-dim: rgba(255, 157, 0, 0.14);
    --orange-glow: rgba(255, 157, 0, 0.35);

    /* Dark warm backgrounds */
    --bg-deepest: #16100a;
    --bg-deep: #1d1610;
    --bg-base: #241c14;
    --bg-raised: #2d2419;
    --bg-hover: #3a2e1f;
    --bg-active: #46371f;

    --border: rgba(255, 157, 0, 0.12);
    --border-strong: rgba(255, 157, 0, 0.3);

    --text-primary: #f5ede1;
    --text-secondary: #c9b99f;
    --text-muted: #8a7a60;

    --green: #57f287;
    --red: #ed4245;

    --radius: 10px;
    --radius-lg: 16px;

    --font: 'Inter', -apple-system, sans-serif;
    --font-mono: 'Fira Code', monospace;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
    height: 100%;
    overflow: hidden;
    font-family: var(--font);
    background: var(--bg-deepest);
    color: var(--text-primary);
}

body {
    display: flex;
    flex-direction: column;
}

/* ---------- Scrollbars ---------- */
.scrollbar-thin::-webkit-scrollbar { width: 8px; height: 8px; }
.scrollbar-thin::-webkit-scrollbar-track { background: transparent; }
.scrollbar-thin::-webkit-scrollbar-thumb {
    background: rgba(255, 157, 0, 0.25);
    border-radius: 4px;
}
.scrollbar-thin::-webkit-scrollbar-thumb:hover { background: rgba(255, 157, 0, 0.45); }

.hidden { display: none !important; }

/* =========================================================
   Top bar
   ========================================================= */
.topbar {
    display: flex;
    align-items: center;
    gap: 24px;
    padding: 0 20px;
    height: 58px;
    flex-shrink: 0;
    background: linear-gradient(180deg, #241a0e 0%, #1d1610 100%);
    border-bottom: 1px solid var(--border-strong);
    box-shadow: 0 2px 16px rgba(255, 107, 0, 0.08);
    z-index: 50;
}

.brand {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 19px;
    font-weight: 800;
    letter-spacing: -0.3px;
    white-space: nowrap;
}
.brand-emoji { font-size: 24px; filter: drop-shadow(0 0 8px var(--orange-glow)); }
.brand-accent {
    background: linear-gradient(90deg, var(--orange), var(--orange-deep));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.mode-tabs {
    display: flex;
    gap: 6px;
    background: var(--bg-deepest);
    padding: 5px;
    border-radius: 12px;
    border: 1px solid var(--border);
}

.mode-tab {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 18px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-secondary);
    font-family: var(--font);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.18s ease;
}
.mode-tab:hover { color: var(--text-primary); background: var(--bg-hover); }
.mode-tab.active {
    background: linear-gradient(135deg, var(--orange), var(--orange-deep));
    color: #1a1006;
    box-shadow: 0 2px 12px var(--orange-glow);
}

.topbar-stats {
    margin-left: auto;
    display: flex;
    gap: 8px;
    align-items: center;
}
.stat-pill {
    padding: 6px 12px;
    border-radius: 999px;
    background: var(--orange-dim);
    border: 1px solid var(--border);
    color: var(--orange-bright);
    font-size: 12.5px;
    font-weight: 600;
    white-space: nowrap;
}
.stat-link { text-decoration: none; transition: all 0.15s; }
.stat-link:hover { border-color: var(--orange); box-shadow: 0 0 10px var(--orange-glow); }

/* =========================================================
   Mode panels
   ========================================================= */
.mode-panel {
    display: none;
    flex: 1;
    min-height: 0;
}
.mode-panel.active { display: flex; }

/* =========================================================
   DISCORD MODE
   ========================================================= */
.discord-shell {
    display: flex;
    flex: 1;
    min-height: 0;
    width: 100%;
}

/* --- Server rail --- */
.server-bar {
    width: 72px;
    flex-shrink: 0;
    background: var(--bg-deepest);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 12px;
    gap: 8px;
}
.server-icon {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: var(--bg-raised);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: var(--text-secondary);
    font-size: 22px;
    transition: all 0.2s ease;
    position: relative;
}
.server-icon:hover { border-radius: 16px; background: var(--orange-deep); color: #fff; }
.server-icon.active {
    border-radius: 16px;
    background: linear-gradient(135deg, var(--orange), var(--orange-deep));
    color: #1a1006;
}
.server-icon.active::before {
    content: '';
    position: absolute;
    left: -12px;
    width: 4px;
    height: 36px;
    border-radius: 0 4px 4px 0;
    background: var(--orange-bright);
}
.guild-initials { font-weight: 800; font-size: 17px; }
.server-separator {
    width: 32px;
    height: 2px;
    background: var(--border-strong);
    border-radius: 1px;
    margin: 2px 0;
}

/* --- Channels sidebar --- */
.sidebar {
    width: 250px;
    flex-shrink: 0;
    background: var(--bg-deep);
    display: flex;
    flex-direction: column;
    border-right: 1px solid var(--border);
}
.sidebar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    border-bottom: 1px solid var(--border);
    box-shadow: 0 1px 4px rgba(0,0,0,0.3);
}
.server-name { font-size: 15.5px; font-weight: 700; }
.server-badge {
    font-size: 9.5px;
    font-weight: 800;
    letter-spacing: 0.8px;
    color: #1a1006;
    background: linear-gradient(135deg, var(--orange), var(--orange-deep));
    padding: 3px 7px;
    border-radius: 4px;
}

.channels-scroller {
    flex: 1;
    overflow-y: auto;
    padding: 12px 8px;
}

.channel-category {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 14px 8px 4px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    text-transform: uppercase;
    cursor: pointer;
    user-select: none;
}
.channel-category:hover { color: var(--orange-bright); }
.category-arrow { font-size: 8px; transition: transform 0.15s; }
.channel-category.collapsed .category-arrow { transform: rotate(-90deg); }

.channel-item {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 6px 10px;
    margin: 1px 0;
    border-radius: 6px;
    color: var(--text-secondary);
    font-size: 14.5px;
    cursor: pointer;
    transition: all 0.12s;
}
.channel-item:hover { background: var(--bg-hover); color: var(--text-primary); }
.channel-item.active {
    background: var(--orange-dim);
    color: var(--orange-bright);
    font-weight: 600;
}
.channel-item .hash { color: var(--text-muted); font-weight: 500; }
.channel-item.active .hash { color: var(--orange); }
.channel-item .ch-name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.channel-item .ch-count {
    font-size: 11px;
    color: var(--text-muted);
    background: var(--bg-deepest);
    padding: 1px 7px;
    border-radius: 999px;
}
.channel-item.active .ch-count { color: var(--orange-bright); }

.sidebar-footer {
    padding: 10px;
    background: var(--bg-deepest);
    border-top: 1px solid var(--border);
}
.user-area { display: flex; align-items: center; gap: 10px; }
.user-area-text { display: flex; flex-direction: column; }
.user-area-name { font-size: 13px; font-weight: 600; }
.user-area-sub { font-size: 11px; color: var(--text-muted); }

/* --- Chat pane --- */
.chat-pane {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    background: var(--bg-base);
}
.chat-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 13px 18px;
    border-bottom: 1px solid var(--border);
    box-shadow: 0 1px 4px rgba(0,0,0,0.25);
    flex-shrink: 0;
}
.channel-hash { font-size: 22px; color: var(--orange); font-weight: 600; }
.channel-title { font-size: 16px; font-weight: 700; }
.channel-count { font-size: 12.5px; color: var(--text-muted); margin-left: 8px; }

.messages-scroller {
    flex: 1;
    overflow-y: auto;
    padding: 16px 4px 24px;
}

.btn-more {
    display: block;
    margin: 8px auto 16px;
    padding: 8px 22px;
    border: 1px solid var(--border-strong);
    border-radius: 999px;
    background: var(--orange-dim);
    color: var(--orange-bright);
    font-family: var(--font);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
}
.btn-more:hover { background: var(--orange); color: #1a1006; box-shadow: 0 0 14px var(--orange-glow); }
.btn-more:disabled { opacity: 0.5; cursor: wait; }

/* --- Messages --- */
.msg-group {
    display: flex;
    gap: 14px;
    padding: 4px 18px;
    margin-top: 14px;
}
.msg-group:hover { background: rgba(255, 157, 0, 0.03); }
.msg-group.highlighted {
    background: var(--orange-dim);
    border-left: 3px solid var(--orange);
    animation: flash-target 1.6s ease;
}
@keyframes flash-target {
    0% { background: var(--orange-glow); }
    100% { background: var(--orange-dim); }
}

.avatar {
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 16px;
    color: #fff;
    background: hsl(var(--avatar-hue, 28), 65%, 45%);
    user-select: none;
}
.avatar-sm { width: 32px; height: 32px; font-size: 14px; }

.msg-body { flex: 1; min-width: 0; }
.msg-header { display: flex; align-items: baseline; gap: 8px; }
.msg-author { font-size: 15px; font-weight: 600; color: var(--orange-bright); }
.msg-time { font-size: 11.5px; color: var(--text-muted); }
.msg-content {
    font-size: 14.5px;
    line-height: 1.55;
    color: var(--text-primary);
    white-space: pre-wrap;
    word-break: break-word;
    margin-top: 1px;
}
.msg-content.followup { padding: 1px 0; }
.msg-content a { color: var(--orange-bright); }
.msg-content code {
    font-family: var(--font-mono);
    font-size: 13px;
    background: var(--bg-deepest);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 1px 5px;
}

.date-divider {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 22px 18px 6px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 600;
}
.date-divider::before, .date-divider::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--border);
}

/* --- Fake input bar --- */
.chat-input-bar { padding: 0 18px 20px; flex-shrink: 0; }
.fake-input {
    display: flex;
    align-items: center;
    gap: 12px;
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 11px 16px;
    cursor: not-allowed;
    opacity: 0.75;
}
.fake-input-plus {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--text-muted);
    color: var(--bg-deepest);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
}
.fake-input-text { color: var(--text-muted); font-size: 14px; }

/* --- Empty / loading states --- */
.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    gap: 8px;
    color: var(--text-muted);
    text-align: center;
    padding: 40px;
}
.empty-emoji { font-size: 48px; margin-bottom: 6px; }
.empty-state h3 { color: var(--text-secondary); font-size: 18px; }
.empty-state p { font-size: 14px; max-width: 360px; }

.loading-spinner {
    display: flex;
    justify-content: center;
    padding: 48px;
}
.spinner {
    width: 36px;
    height: 36px;
    border: 3px solid var(--orange-dim);
    border-top-color: var(--orange);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* =========================================================
   SEARCH MODE
   ========================================================= */
.search-shell {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    width: 100%;
    max-width: 980px;
    margin: 0 auto;
    padding: 26px 24px 0;
}

.search-controls { flex-shrink: 0; }
.search-title { font-size: 26px; font-weight: 800; }
.search-sub { color: var(--text-muted); font-size: 14px; margin: 4px 0 18px; }

.search-row { display: flex; gap: 12px; }

.user-select {
    background: var(--bg-raised);
    border: 1px solid var(--border-strong);
    border-radius: var(--radius);
    color: var(--text-primary);
    font-family: var(--font);
    font-size: 14.5px;
    font-weight: 500;
    padding: 12px 14px;
    cursor: pointer;
    max-width: 260px;
    transition: border-color 0.15s;
}
.user-select:hover, .user-select:focus { border-color: var(--orange); outline: none; }
.user-select-lg { width: 100%; max-width: 420px; font-size: 16px; }

.search-input-wrap { position: relative; flex: 1; display: flex; align-items: center; }
.search-input-icon {
    position: absolute;
    left: 14px;
    color: var(--text-muted);
    pointer-events: none;
}
.search-input {
    width: 100%;
    background: var(--bg-raised);
    border: 1px solid var(--border-strong);
    border-radius: var(--radius);
    color: var(--text-primary);
    font-family: var(--font);
    font-size: 16px;
    padding: 12px 44px;
    transition: all 0.15s;
}
.search-input:focus {
    outline: none;
    border-color: var(--orange);
    box-shadow: 0 0 0 3px var(--orange-dim), 0 0 18px var(--orange-glow);
}
.search-input::placeholder { color: var(--text-muted); }

.search-live-dot {
    position: absolute;
    right: 16px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--text-muted);
    opacity: 0.4;
    transition: all 0.2s;
}
.search-live-dot.live {
    background: var(--orange);
    opacity: 1;
    box-shadow: 0 0 10px var(--orange-glow);
    animation: pulse 1s ease infinite;
}
@keyframes pulse {
    50% { transform: scale(1.35); }
}

.search-meta {
    margin: 12px 2px 10px;
    font-size: 13.5px;
    color: var(--text-muted);
    font-weight: 500;
}
.search-meta .match-count { color: var(--orange-bright); font-weight: 700; }

.search-results {
    flex: 1;
    overflow-y: auto;
    min-height: 0;
    padding-bottom: 12px;
}

.result-card {
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 13px 16px;
    margin-bottom: 10px;
    cursor: pointer;
    transition: all 0.15s;
    animation: slide-in 0.25s ease both;
}
@keyframes slide-in {
    from { opacity: 0; transform: translateY(6px); }
}
.result-card:hover {
    border-color: var(--orange);
    box-shadow: 0 2px 14px rgba(255, 107, 0, 0.15);
    transform: translateY(-1px);
}
.result-meta {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 6px;
    font-size: 12.5px;
}
.result-author { color: var(--orange-bright); font-weight: 700; font-size: 13.5px; }
.result-channel {
    color: var(--text-secondary);
    background: var(--bg-deepest);
    padding: 2px 8px;
    border-radius: 999px;
    font-weight: 500;
}
.result-time { color: var(--text-muted); margin-left: auto; }
.result-content {
    font-size: 14px;
    line-height: 1.5;
    color: var(--text-primary);
    word-break: break-word;
    white-space: pre-wrap;
}
.result-jump {
    margin-top: 8px;
    font-size: 12px;
    color: var(--text-muted);
}
.result-card:hover .result-jump { color: var(--orange); }

mark {
    background: var(--orange);
    color: #1a1006;
    font-weight: 700;
    border-radius: 3px;
    padding: 0 2px;
    box-shadow: 0 0 8px var(--orange-glow);
}

.search-more-wrap { flex-shrink: 0; padding: 6px 0 16px; text-align: center; }

/* =========================================================
   FUN FACTS MODE
   ========================================================= */
.facts-shell {
    flex: 1;
    overflow-y: auto;
    width: 100%;
    padding: 26px 24px 48px;
}
.facts-controls {
    max-width: 1100px;
    margin: 0 auto 24px;
}
.facts-title { font-size: 26px; font-weight: 800; }
.facts-sub { color: var(--text-muted); font-size: 14px; margin: 4px 0 16px; }

#facts-content { max-width: 1100px; margin: 0 auto; }

.facts-hero {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
    margin-bottom: 18px;
}
.hero-stat {
    background: linear-gradient(135deg, var(--bg-raised), var(--bg-base));
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 16px;
    text-align: center;
    transition: all 0.2s;
}
.hero-stat:hover { border-color: var(--orange); transform: translateY(-2px); }
.hero-stat-value {
    font-size: 26px;
    font-weight: 800;
    background: linear-gradient(90deg, var(--orange-bright), var(--orange-deep));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1.2;
    word-break: break-word;
}
.hero-stat-label {
    font-size: 11.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--text-muted);
    margin-top: 6px;
}

.facts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 16px;
}

.fact-card {
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 18px;
    animation: slide-in 0.3s ease both;
}
.fact-card-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 14px;
    color: var(--orange-bright);
}
.fact-card-title .fact-emoji { font-size: 18px; }

.bar-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}
.bar-label {
    width: 130px;
    flex-shrink: 0;
    font-size: 13px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: right;
    font-family: var(--font-mono);
}
.bar-track {
    flex: 1;
    height: 18px;
    background: var(--bg-deepest);
    border-radius: 4px;
    overflow: hidden;
}
.bar-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--orange-deep), var(--orange));
    border-radius: 4px;
    transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
    box-shadow: 0 0 8px rgba(255, 107, 0, 0.3);
}
.bar-count {
    width: 52px;
    flex-shrink: 0;
    font-size: 12px;
    color: var(--text-muted);
    font-family: var(--font-mono);
}

.fact-blockquote {
    background: var(--bg-deepest);
    border-left: 3px solid var(--orange);
    border-radius: 6px;
    padding: 12px 14px;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--text-secondary);
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 180px;
    overflow-y: auto;
}

.hour-chart {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    height: 90px;
    margin-top: 6px;
}
.hour-bar-wrap {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    height: 100%;
    justify-content: flex-end;
}
.hour-bar {
    width: 100%;
    background: linear-gradient(180deg, var(--orange), var(--orange-deep));
    border-radius: 3px 3px 0 0;
    min-height: 2px;
    transition: height 0.5s ease;
    opacity: 0.85;
}
.hour-bar-wrap:hover .hour-bar { opacity: 1; box-shadow: 0 0 8px var(--orange-glow); }
.hour-bar-wrap.peak .hour-bar { background: var(--orange-bright); opacity: 1; }
.hour-label { font-size: 8.5px; color: var(--text-muted); font-family: var(--font-mono); }

.fact-card.wide { grid-column: 1 / -1; }

/* =========================================================
   Responsive
   ========================================================= */
@media (max-width: 900px) {
    .topbar { gap: 12px; padding: 0 12px; }
    .topbar-stats { display: none; }
    .mode-tab { padding: 8px 12px; font-size: 13px; }
    .server-bar { display: none; }
    .sidebar { width: 200px; }
    .bar-label { width: 90px; }
}
@media (max-width: 640px) {
    .brand-name { display: none; }
    .sidebar { width: 160px; }
    .search-row { flex-direction: column; }
    .user-select { max-width: none; }
}

input.content:
// =========================================================
// Glint Archive — Discord / Search / Fun Facts
// =========================================================

const state = {
    mode: 'discord',
    categories: {},
    users: [],
    // discord mode
    currentChannelId: null,
    currentChannelName: '',
    channelTotal: 0,
    channelOffset: 0,
    // search mode
    searchQuery: '',
    searchAuthor: '__all__',
    searchOffset: 0,
    searchTotal: 0,
    searchSeq: 0,
    // fun facts
    factsAuthor: '__all__',
};

const $ = (id) => document.getElementById(id);

// ---------------------------------------------------------
// Utilities
// ---------------------------------------------------------
function escapeHtml(str) {
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Escape, then wrap query matches in <mark>
function highlightHtml(text, query) {
    const escaped = escapeHtml(text);
    if (!query) return escaped;
    const re = new RegExp(escapeRegex(escapeHtml(query)), 'gi');
    return escaped.replace(re, (m) => `<mark>${m}</mark>`);
}

function avatarHue(name) {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
    return h % 360;
}

function avatarHtml(name, small = false) {
    const initial = (name || '?').trim().charAt(0).toUpperCase() || '?';
    return `<div class="avatar${small ? ' avatar-sm' : ''}" style="--avatar-hue:${avatarHue(name)}">${escapeHtml(initial)}</div>`;
}

function fmtTime(ts) {
    const d = new Date(ts);
    if (isNaN(d)) return ts;
    return d.toLocaleString(undefined, {
        month: 'short', day: 'numeric', year: 'numeric',
        hour: 'numeric', minute: '2-digit',
    });
}

function fmtDate(ts) {
    const d = new Date(ts);
    if (isNaN(d)) return '';
    return d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
}

function fmtNum(n) {
    return Number(n).toLocaleString();
}

async function api(path, params = {}) {
    const url = new URL(path, window.location.origin);
    for (const [k, v] of Object.entries(params)) {
        if (v !== null && v !== undefined && v !== '') url.searchParams.set(k, v);
    }
    const res = await fetch(url);
    if (!res.ok) throw new Error(`API ${path} failed: ${res.status}`);
    return res.json();
}

// ---------------------------------------------------------
// Mode switching
// ---------------------------------------------------------
document.querySelectorAll('.mode-tab').forEach((tab) => {
    tab.addEventListener('click', () => setMode(tab.dataset.mode));
});

function setMode(mode) {
    state.mode = mode;
    document.querySelectorAll('.mode-tab').forEach((t) =>
        t.classList.toggle('active', t.dataset.mode === mode));
    document.querySelectorAll('.mode-panel').forEach((p) =>
        p.classList.toggle('active', p.id === `mode-${mode}`));
    if (mode === 'search') $('search-input').focus();
    if (mode === 'funfacts' && !$('facts-content').dataset.loaded) loadFunFacts();
}

// ---------------------------------------------------------
// Boot: channels, users, stats
// ---------------------------------------------------------
async function boot() {
    try {
        const [channels, users, stats] = await Promise.all([
            api('/api/channels'),
            api('/api/users'),
            api('/api/stats'),
        ]);
        state.categories = channels.categories;
        state.users = users.users;
        renderChannels();
        populateUserSelects();
        $('stat-messages').textContent = `💬 ${fmtNum(stats.total_messages)} msgs`;
        $('stat-users').textContent = `👤 ${fmtNum(stats.unique_users)} users`;
    } catch (e) {
        console.error(e);
        $('channels-list').innerHTML = `<div class="empty-state"><p>Failed to load: ${escapeHtml(e.message)}</p></div>`;
    }
}

const CATEGORY_EMOJI = {
    'INFORMATION': '📢', 'GENERAL': '💬', 'DEVELOPMENT': '🛠️',
    'BOTS & TOOLS': '🤖', 'TICKETS & HELP': '🎫', 'MISC': '📦',
};

function renderChannels() {
    const container = $('channels-list');
    container.innerHTML = '';
    for (const [category, channels] of Object.entries(state.categories)) {
        const catEl = document.createElement('div');
        catEl.className = 'channel-category';
        catEl.innerHTML = `<span class="category-arrow">▼</span> ${CATEGORY_EMOJI[category] || ''} ${escapeHtml(category)}`;
        container.appendChild(catEl);

        const group = document.createElement('div');
        channels.forEach((ch) => {
            const el = document.createElement('div');
            el.className = 'channel-item';
            el.dataset.channelId = ch.id;
            el.innerHTML = `<span class="hash">#</span><span class="ch-name">${escapeHtml(ch.name)}</span><span class="ch-count">${fmtNum(ch.count)}</span>`;
            el.addEventListener('click', () => openChannel(ch.id, ch.name));
            group.appendChild(el);
        });
        container.appendChild(group);

        catEl.addEventListener('click', () => {
            catEl.classList.toggle('collapsed');
            group.style.display = catEl.classList.contains('collapsed') ? 'none' : '';
        });
    }
}

function populateUserSelects() {
    for (const selectId of ['search-user-select', 'facts-user-select']) {
        const sel = $(selectId);
        state.users.forEach((u) => {
            const opt = document.createElement('option');
            opt.value = u.name;
            opt.textContent = `${u.name} (${fmtNum(u.count)})`;
            sel.appendChild(opt);
        });
    }
}

// ---------------------------------------------------------
// DISCORD MODE
// ---------------------------------------------------------
async function openChannel(channelId, channelName) {
    state.currentChannelId = channelId;
    state.currentChannelName = channelName;
    document.querySelectorAll('.channel-item').forEach((el) =>
        el.classList.toggle('active', el.dataset.channelId === channelId));
    $('chat-channel-name').textContent = channelName;
    $('chat-channel-count').textContent = '';
    const list = $('messages-list');
    list.innerHTML = '<div class="loading-spinner"><div class="spinner"></div></div>';

    try {
        const data = await api('/api/messages', { channel_id: channelId, limit: 100 });
        state.channelTotal = data.total;
        state.channelOffset = data.offset;
        $('chat-channel-count').textContent = `${fmtNum(data.total)} messages`;
        renderMessages(data.messages, { scrollToBottom: true });
    } catch (e) {
        list.innerHTML = `<div class="empty-state"><p>Failed to load channel: ${escapeHtml(e.message)}</p></div>`;
    }
}

function buildMessageGroups(messages, highlightId = null, query = null) {
    const frag = document.createDocumentFragment();
    let lastAuthor = null;
    let lastDate = null;
    let lastTs = 0;
    let currentGroup = null;

    messages.forEach((msg) => {
        const d = new Date(msg.timestamp);
        const dateStr = isNaN(d) ? '' : d.toDateString();
        const ms = isNaN(d) ? 0 : d.getTime();

        if (dateStr !== lastDate) {
            const div = document.createElement('div');
            div.className = 'date-divider';
            div.textContent = fmtDate(msg.timestamp);
            frag.appendChild(div);
            lastDate = dateStr;
            lastAuthor = null;
        }

        const sameGroup = msg.author === lastAuthor && (ms - lastTs) < 5 * 60 * 1000;
        const contentHtml = query ? highlightHtml(msg.content, query) : escapeHtml(msg.content);

        if (sameGroup && currentGroup) {
            const p = document.createElement('div');
            p.className = 'msg-content followup';
            p.dataset.messageId = msg.message_id;
            p.innerHTML = contentHtml;
            currentGroup.querySelector('.msg-body').appendChild(p);
            if (msg.message_id === highlightId) currentGroup.classList.add('highlighted');
        } else {
            const group = document.createElement('div');
            group.className = 'msg-group';
            group.dataset.messageId = msg.message_id;
            group.innerHTML = `
                ${avatarHtml(msg.author)}
                <div class="msg-body">
                    <div class="msg-header">
                        <span class="msg-author">${escapeHtml(msg.author)}</span>
                        <span class="msg-time">${fmtTime(msg.timestamp)}</span>
                    </div>
                    <div class="msg-content">${contentHtml}</div>
                </div>`;
            if (msg.message_id === highlightId) group.classList.add('highlighted');
            frag.appendChild(group);
            currentGroup = group;
        }
        lastAuthor = msg.author;
        lastTs = ms;
    });
    return frag;
}

function renderMessages(messages, { scrollToBottom = false, highlightId = null } = {}) {
    const list = $('messages-list');
    list.innerHTML = '';

    if (state.channelOffset > 0) {
        const btn = document.createElement('button');
        btn.className = 'btn-more';
        btn.textContent = `Load older messages (${fmtNum(state.channelOffset)} earlier)`;
        btn.addEventListener('click', () => loadOlder(btn));
        list.appendChild(btn);
    }

    if (!messages.length) {
        list.innerHTML = '<div class="empty-state"><div class="empty-emoji">🦗</div><h3>No messages</h3></div>';
        return;
    }

    list.appendChild(buildMessageGroups(messages, highlightId));

    if (highlightId) {
        const target = list.querySelector(`[data-message-id="${CSS.escape(highlightId)}"]`);
        if (target) target.scrollIntoView({ block: 'center' });
    } else if (scrollToBottom) {
        list.scrollTop = list.scrollHeight;
    }
}

async function loadOlder(btn) {
    btn.disabled = true;
    const newOffset = Math.max(0, state.channelOffset - 100);
    const count = state.channelOffset - newOffset;
    try {
        const data = await api('/api/messages', {
            channel_id: state.currentChannelId, limit: count, offset: newOffset,
        });
        state.channelOffset = newOffset;
        const list = $('messages-list');
        const prevHeight = list.scrollHeight;
        btn.remove();
        const frag = buildMessageGroups(data.messages);
        list.insertBefore(frag, list.firstChild);
        if (state.channelOffset > 0) {
            const newBtn = document.createElement('button');
            newBtn.className = 'btn-more';
            newBtn.textContent = `Load older messages (${fmtNum(state.channelOffset)} earlier)`;
            newBtn.addEventListener('click', () => loadOlder(newBtn));
            list.insertBefore(newBtn, list.firstChild);
        }
        list.scrollTop += list.scrollHeight - prevHeight;
    } catch (e) {
        btn.disabled = false;
        console.error(e);
    }
}

// Jump from a search result into Discord-mode context
async function jumpToMessage(messageId) {
    setMode('discord');
    const list = $('messages-list');
    list.innerHTML = '<div class="loading-spinner"><div class="spinner"></div></div>';
    try {
        const data = await api('/api/message_context', { message_id: messageId, limit: 100 });
        state.currentChannelId = data.channel_id;
        state.currentChannelName = data.channel_name;
        state.channelTotal = data.total;
        state.channelOffset = data.offset;
        document.querySelectorAll('.channel-item').forEach((el) =>
            el.classList.toggle('active', el.dataset.channelId === data.channel_id));
        $('chat-channel-name').textContent = data.channel_name;
        $('chat-channel-count').textContent = `${fmtNum(data.total)} messages`;
        renderMessages(data.messages, { highlightId: String(data.target_message_id) });
    } catch (e) {
        list.innerHTML = `<div class="empty-state"><p>Could not load context: ${escapeHtml(e.message)}</p></div>`;
    }
}

// ---------------------------------------------------------
// SEARCH MODE
// ---------------------------------------------------------
let searchDebounce = null;

$('search-input').addEventListener('input', () => {
    clearTimeout(searchDebounce);
    $('search-live-dot').classList.add('live');
    searchDebounce = setTimeout(runSearch, 220);
});
$('search-user-select').addEventListener('change', () => {
    state.searchAuthor = $('search-user-select').value;
    runSearch();
});
$('search-more').addEventListener('click', () => loadMoreSearch());

async function runSearch() {
    const query = $('search-input').value.trim();
    state.searchQuery = query;
    state.searchOffset = 0;
    const seq = ++state.searchSeq;
    const results = $('search-results');
    const meta = $('search-meta');

    if (query.length < 2) {
        $('search-live-dot').classList.remove('live');
        meta.textContent = query.length === 0 ? 'Waiting for input…' : 'Keep typing (2+ characters)…';
        results.innerHTML = '<div class="empty-state"><div class="empty-emoji">⌨️</div><h3>Start typing</h3><p>Pick a user (or all) and type — results stream in as you type.</p></div>';
        $('search-more').classList.add('hidden');
        return;
    }

    try {
        const data = await api('/api/search', { query, author: state.searchAuthor, limit: 50 });
        if (seq !== state.searchSeq) return; // stale response
        $('search-live-dot').classList.remove('live');
        state.searchTotal = data.total;
        const who = state.searchAuthor === '__all__' ? 'all users' : state.searchAuthor;
        meta.innerHTML = `<span class="match-count">${fmtNum(data.total)}</span> match${data.total === 1 ? '' : 'es'} for "<b>${escapeHtml(query)}</b>" from ${escapeHtml(who)}`;

        results.innerHTML = '';
        if (!data.messages.length) {
            results.innerHTML = '<div class="empty-state"><div class="empty-emoji">🤷</div><h3>No matches</h3><p>Try a different phrase or user.</p></div>';
            $('search-more').classList.add('hidden');
            return;
        }
        appendSearchResults(data.messages, query);
        state.searchOffset = data.messages.length;
        $('search-more').classList.toggle('hidden', state.searchOffset >= data.total);
    } catch (e) {
        if (seq !== state.searchSeq) return;
        $('search-live-dot').classList.remove('live');
        meta.textContent = `Search failed: ${e.message}`;
    }
}

function appendSearchResults(messages, query) {
    const results = $('search-results');
    messages.forEach((msg, i) => {
        const card = document.createElement('div');
        card.className = 'result-card';
        card.style.animationDelay = `${Math.min(i * 20, 300)}ms`;
        card.innerHTML = `
            <div class="result-meta">
                <span class="result-author">${escapeHtml(msg.author)}</span>
                <span class="result-channel"># ${escapeHtml(msg.channel_name || '')}</span>
                <span class="result-time">${fmtTime(msg.timestamp)}</span>
            </div>
            <div class="result-content">${highlightHtml(msg.content, query)}</div>
            <div class="result-jump">↪ Click to view in context</div>`;
        card.addEventListener('click', () => jumpToMessage(msg.message_id));
        results.appendChild(card);
    });
}

async function loadMoreSearch() {
    const btn = $('search-more');
    btn.disabled = true;
    try {
        const data = await api('/api/search', {
            query: state.searchQuery, author: state.searchAuthor,
            limit: 50, offset: state.searchOffset,
        });
        appendSearchResults(data.messages, state.searchQuery);
        state.searchOffset += data.messages.length;
        btn.classList.toggle('hidden', state.searchOffset >= state.searchTotal);
    } catch (e) {
        console.error(e);
    } finally {
        btn.disabled = false;
    }
}

// ---------------------------------------------------------
// FUN FACTS MODE
// ---------------------------------------------------------
$('facts-user-select').addEventListener('change', () => {
    state.factsAuthor = $('facts-user-select').value;
    loadFunFacts();
});

async function loadFunFacts() {
    const container = $('facts-content');
    container.dataset.loaded = '1';
    container.innerHTML = '<div class="loading-spinner"><div class="spinner"></div></div>';
    try {
        const f = await api('/api/funfacts', { author: state.factsAuthor });
        renderFunFacts(f);
    } catch (e) {
        container.innerHTML = `<div class="empty-state"><p>Failed: ${escapeHtml(e.message)}</p></div>`;
    }
}

function barListHtml(items, { mono = true } = {}) {
    if (!items || !items.length) return '<p style="color: var(--text-muted); font-size: 13px;">Not enough data 🤷</p>';
    const max = items[0].count || 1;
    return items.map((it) => `
        <div class="bar-row">
            <span class="bar-label" title="${escapeHtml(it.value)}">${escapeHtml(it.value)}</span>
            <div class="bar-track"><div class="bar-fill" style="width:${Math.max(3, (it.count / max) * 100)}%"></div></div>
            <span class="bar-count">${fmtNum(it.count)}×</span>
        </div>`).join('');
}

function hourChartHtml(hist, peak) {
    const max = Math.max(1, ...Object.values(hist || {}));
    let bars = '';
    for (let h = 0; h < 24; h++) {
        const c = hist?.[h] || 0;
        const pct = Math.round((c / max) * 100);
        bars += `
            <div class="hour-bar-wrap${h === peak ? ' peak' : ''}" title="${h}:00 — ${fmtNum(c)} messages">
                <div class="hour-bar" style="height:${Math.max(2, pct)}%"></div>
                <span class="hour-label">${h % 6 === 0 ? h : ''}</span>
            </div>`;
    }
    return `<div class="hour-chart">${bars}</div>`;
}

function renderFunFacts(f) {
    const container = $('facts-content');
    const topBigram = f.top_bigrams[0];
    const topTrigram = f.top_trigrams[0];
    const topLetter = f.top_letters[0];
    const topWord = f.top_words[0];

    container.innerHTML = `
        <div class="facts-hero">
            <div class="hero-stat">
                <div class="hero-stat-value">${fmtNum(f.message_count)}</div>
                <div class="hero-stat-label">Messages</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${fmtNum(f.total_words)}</div>
                <div class="hero-stat-label">Words typed</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${f.avg_words_per_message}</div>
                <div class="hero-stat-label">Avg words / msg</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${topLetter ? `"${escapeHtml(topLetter.value)}"` : '—'}</div>
                <div class="hero-stat-label">Favorite letter</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${topWord ? escapeHtml(topWord.value) : '—'}</div>
                <div class="hero-stat-label">Favorite word</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${f.busiest_hour !== null ? f.busiest_hour + ':00' : '—'}</div>
                <div class="hero-stat-label">Busiest hour</div>
            </div>
        </div>

        <div class="facts-grid">
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">👯</span> Top Bigrams ${topBigram ? `— "${escapeHtml(topBigram.value)}"` : ''}</div>
                ${barListHtml(f.top_bigrams)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🎰</span> Top Trigrams ${topTrigram ? `— "${escapeHtml(topTrigram.value)}"` : ''}</div>
                ${barListHtml(f.top_trigrams)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">📝</span> Top Words <small style="color:var(--text-muted); font-weight: 400;">(stopwords removed)</small></div>
                ${barListHtml(f.top_words)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🔤</span> Letter Frequency</div>
                ${barListHtml(f.top_letters)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">😀</span> Top Emoji</div>
                ${barListHtml(f.top_emoji)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🏠</span> Favorite Channels</div>
                ${barListHtml(f.favorite_channels)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🕐</span> Activity by Hour ${f.busiest_day ? `— peaks on ${escapeHtml(f.busiest_day)}s` : ''}</div>
                ${hourChartHtml(f.hour_histogram, f.busiest_hour)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🎭</span> Personality Stats</div>
                ${barListHtml([
                    { value: 'questions ?', count: f.question_messages },
                    { value: 'exclaims !', count: f.exclaim_messages },
                    { value: 'ALL CAPS', count: f.caps_messages },
                ].sort((a, b) => b.count - a.count))}
            </div>
            <div class="fact-card wide">
                <div class="fact-card-title"><span class="fact-emoji">📜</span> Longest Message Ever (${fmtNum(f.longest_message_length)} chars)</div>
                <div class="fact-blockquote">${escapeHtml(f.longest_message)}${f.longest_message_length > 500 ? '…' : ''}</div>
            </div>
        </div>`;
}

// ---------------------------------------------------------
boot();

toolUseResult.content:
// =========================================================
// Glint Archive — Discord / Search / Fun Facts
// =========================================================

const state = {
    mode: 'discord',
    categories: {},
    users: [],
    // discord mode
    currentChannelId: null,
    currentChannelName: '',
    channelTotal: 0,
    channelOffset: 0,
    // search mode
    searchQuery: '',
    searchAuthor: '__all__',
    searchOffset: 0,
    searchTotal: 0,
    searchSeq: 0,
    // fun facts
    factsAuthor: '__all__',
};

const $ = (id) => document.getElementById(id);

// ---------------------------------------------------------
// Utilities
// ---------------------------------------------------------
function escapeHtml(str) {
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Escape, then wrap query matches in <mark>
function highlightHtml(text, query) {
    const escaped = escapeHtml(text);
    if (!query) return escaped;
    const re = new RegExp(escapeRegex(escapeHtml(query)), 'gi');
    return escaped.replace(re, (m) => `<mark>${m}</mark>`);
}

function avatarHue(name) {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
    return h % 360;
}

function avatarHtml(name, small = false) {
    const initial = (name || '?').trim().charAt(0).toUpperCase() || '?';
    return `<div class="avatar${small ? ' avatar-sm' : ''}" style="--avatar-hue:${avatarHue(name)}">${escapeHtml(initial)}</div>`;
}

function fmtTime(ts) {
    const d = new Date(ts);
    if (isNaN(d)) return ts;
    return d.toLocaleString(undefined, {
        month: 'short', day: 'numeric', year: 'numeric',
        hour: 'numeric', minute: '2-digit',
    });
}

function fmtDate(ts) {
    const d = new Date(ts);
    if (isNaN(d)) return '';
    return d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
}

function fmtNum(n) {
    return Number(n).toLocaleString();
}

async function api(path, params = {}) {
    const url = new URL(path, window.location.origin);
    for (const [k, v] of Object.entries(params)) {
        if (v !== null && v !== undefined && v !== '') url.searchParams.set(k, v);
    }
    const res = await fetch(url);
    if (!res.ok) throw new Error(`API ${path} failed: ${res.status}`);
    return res.json();
}

// ---------------------------------------------------------
// Mode switching
// ---------------------------------------------------------
document.querySelectorAll('.mode-tab').forEach((tab) => {
    tab.addEventListener('click', () => setMode(tab.dataset.mode));
});

function setMode(mode) {
    state.mode = mode;
    document.querySelectorAll('.mode-tab').forEach((t) =>
        t.classList.toggle('active', t.dataset.mode === mode));
    document.querySelectorAll('.mode-panel').forEach((p) =>
        p.classList.toggle('active', p.id === `mode-${mode}`));
    if (mode === 'search') $('search-input').focus();
    if (mode === 'funfacts' && !$('facts-content').dataset.loaded) loadFunFacts();
}

// ---------------------------------------------------------
// Boot: channels, users, stats
// ---------------------------------------------------------
async function boot() {
    try {
        const [channels, users, stats] = await Promise.all([
            api('/api/channels'),
            api('/api/users'),
            api('/api/stats'),
        ]);
        state.categories = channels.categories;
        state.users = users.users;
        renderChannels();
        populateUserSelects();
        $('stat-messages').textContent = `💬 ${fmtNum(stats.total_messages)} msgs`;
        $('stat-users').textContent = `👤 ${fmtNum(stats.unique_users)} users`;
    } catch (e) {
        console.error(e);
        $('channels-list').innerHTML = `<div class="empty-state"><p>Failed to load: ${escapeHtml(e.message)}</p></div>`;
    }
}

const CATEGORY_EMOJI = {
    'INFORMATION': '📢', 'GENERAL': '💬', 'DEVELOPMENT': '🛠️',
    'BOTS & TOOLS': '🤖', 'TICKETS & HELP': '🎫', 'MISC': '📦',
};

function renderChannels() {
    const container = $('channels-list');
    container.innerHTML = '';
    for (const [category, channels] of Object.entries(state.categories)) {
        const catEl = document.createElement('div');
        catEl.className = 'channel-category';
        catEl.innerHTML = `<span class="category-arrow">▼</span> ${CATEGORY_EMOJI[category] || ''} ${escapeHtml(category)}`;
        container.appendChild(catEl);

        const group = document.createElement('div');
        channels.forEach((ch) => {
            const el = document.createElement('div');
            el.className = 'channel-item';
            el.dataset.channelId = ch.id;
            el.innerHTML = `<span class="hash">#</span><span class="ch-name">${escapeHtml(ch.name)}</span><span class="ch-count">${fmtNum(ch.count)}</span>`;
            el.addEventListener('click', () => openChannel(ch.id, ch.name));
            group.appendChild(el);
        });
        container.appendChild(group);

        catEl.addEventListener('click', () => {
            catEl.classList.toggle('collapsed');
            group.style.display = catEl.classList.contains('collapsed') ? 'none' : '';
        });
    }
}

function populateUserSelects() {
    for (const selectId of ['search-user-select', 'facts-user-select']) {
        const sel = $(selectId);
        state.users.forEach((u) => {
            const opt = document.createElement('option');
            opt.value = u.name;
            opt.textContent = `${u.name} (${fmtNum(u.count)})`;
            sel.appendChild(opt);
        });
    }
}

// ---------------------------------------------------------
// DISCORD MODE
// ---------------------------------------------------------
async function openChannel(channelId, channelName) {
    state.currentChannelId = channelId;
    state.currentChannelName = channelName;
    document.querySelectorAll('.channel-item').forEach((el) =>
        el.classList.toggle('active', el.dataset.channelId === channelId));
    $('chat-channel-name').textContent = channelName;
    $('chat-channel-count').textContent = '';
    const list = $('messages-list');
    list.innerHTML = '<div class="loading-spinner"><div class="spinner"></div></div>';

    try {
        const data = await api('/api/messages', { channel_id: channelId, limit: 100 });
        state.channelTotal = data.total;
        state.channelOffset = data.offset;
        $('chat-channel-count').textContent = `${fmtNum(data.total)} messages`;
        renderMessages(data.messages, { scrollToBottom: true });
    } catch (e) {
        list.innerHTML = `<div class="empty-state"><p>Failed to load channel: ${escapeHtml(e.message)}</p></div>`;
    }
}

function buildMessageGroups(messages, highlightId = null, query = null) {
    const frag = document.createDocumentFragment();
    let lastAuthor = null;
    let lastDate = null;
    let lastTs = 0;
    let currentGroup = null;

    messages.forEach((msg) => {
        const d = new Date(msg.timestamp);
        const dateStr = isNaN(d) ? '' : d.toDateString();
        const ms = isNaN(d) ? 0 : d.getTime();

        if (dateStr !== lastDate) {
            const div = document.createElement('div');
            div.className = 'date-divider';
            div.textContent = fmtDate(msg.timestamp);
            frag.appendChild(div);
            lastDate = dateStr;
            lastAuthor = null;
        }

        const sameGroup = msg.author === lastAuthor && (ms - lastTs) < 5 * 60 * 1000;
        const contentHtml = query ? highlightHtml(msg.content, query) : escapeHtml(msg.content);

        if (sameGroup && currentGroup) {
            const p = document.createElement('div');
            p.className = 'msg-content followup';
            p.dataset.messageId = msg.message_id;
            p.innerHTML = contentHtml;
            currentGroup.querySelector('.msg-body').appendChild(p);
            if (msg.message_id === highlightId) currentGroup.classList.add('highlighted');
        } else {
            const group = document.createElement('div');
            group.className = 'msg-group';
            group.dataset.messageId = msg.message_id;
            group.innerHTML = `
                ${avatarHtml(msg.author)}
                <div class="msg-body">
                    <div class="msg-header">
                        <span class="msg-author">${escapeHtml(msg.author)}</span>
                        <span class="msg-time">${fmtTime(msg.timestamp)}</span>
                    </div>
                    <div class="msg-content">${contentHtml}</div>
                </div>`;
            if (msg.message_id === highlightId) group.classList.add('highlighted');
            frag.appendChild(group);
            currentGroup = group;
        }
        lastAuthor = msg.author;
        lastTs = ms;
    });
    return frag;
}

function renderMessages(messages, { scrollToBottom = false, highlightId = null } = {}) {
    const list = $('messages-list');
    list.innerHTML = '';

    if (state.channelOffset > 0) {
        const btn = document.createElement('button');
        btn.className = 'btn-more';
        btn.textContent = `Load older messages (${fmtNum(state.channelOffset)} earlier)`;
        btn.addEventListener('click', () => loadOlder(btn));
        list.appendChild(btn);
    }

    if (!messages.length) {
        list.innerHTML = '<div class="empty-state"><div class="empty-emoji">🦗</div><h3>No messages</h3></div>';
        return;
    }

    list.appendChild(buildMessageGroups(messages, highlightId));

    if (highlightId) {
        const target = list.querySelector(`[data-message-id="${CSS.escape(highlightId)}"]`);
        if (target) target.scrollIntoView({ block: 'center' });
    } else if (scrollToBottom) {
        list.scrollTop = list.scrollHeight;
    }
}

async function loadOlder(btn) {
    btn.disabled = true;
    const newOffset = Math.max(0, state.channelOffset - 100);
    const count = state.channelOffset - newOffset;
    try {
        const data = await api('/api/messages', {
            channel_id: state.currentChannelId, limit: count, offset: newOffset,
        });
        state.channelOffset = newOffset;
        const list = $('messages-list');
        const prevHeight = list.scrollHeight;
        btn.remove();
        const frag = buildMessageGroups(data.messages);
        list.insertBefore(frag, list.firstChild);
        if (state.channelOffset > 0) {
            const newBtn = document.createElement('button');
            newBtn.className = 'btn-more';
            newBtn.textContent = `Load older messages (${fmtNum(state.channelOffset)} earlier)`;
            newBtn.addEventListener('click', () => loadOlder(newBtn));
            list.insertBefore(newBtn, list.firstChild);
        }
        list.scrollTop += list.scrollHeight - prevHeight;
    } catch (e) {
        btn.disabled = false;
        console.error(e);
    }
}

// Jump from a search result into Discord-mode context
async function jumpToMessage(messageId) {
    setMode('discord');
    const list = $('messages-list');
    list.innerHTML = '<div class="loading-spinner"><div class="spinner"></div></div>';
    try {
        const data = await api('/api/message_context', { message_id: messageId, limit: 100 });
        state.currentChannelId = data.channel_id;
        state.currentChannelName = data.channel_name;
        state.channelTotal = data.total;
        state.channelOffset = data.offset;
        document.querySelectorAll('.channel-item').forEach((el) =>
            el.classList.toggle('active', el.dataset.channelId === data.channel_id));
        $('chat-channel-name').textContent = data.channel_name;
        $('chat-channel-count').textContent = `${fmtNum(data.total)} messages`;
        renderMessages(data.messages, { highlightId: String(data.target_message_id) });
    } catch (e) {
        list.innerHTML = `<div class="empty-state"><p>Could not load context: ${escapeHtml(e.message)}</p></div>`;
    }
}

// ---------------------------------------------------------
// SEARCH MODE
// ---------------------------------------------------------
let searchDebounce = null;

$('search-input').addEventListener('input', () => {
    clearTimeout(searchDebounce);
    $('search-live-dot').classList.add('live');
    searchDebounce = setTimeout(runSearch, 220);
});
$('search-user-select').addEventListener('change', () => {
    state.searchAuthor = $('search-user-select').value;
    runSearch();
});
$('search-more').addEventListener('click', () => loadMoreSearch());

async function runSearch() {
    const query = $('search-input').value.trim();
    state.searchQuery = query;
    state.searchOffset = 0;
    const seq = ++state.searchSeq;
    const results = $('search-results');
    const meta = $('search-meta');

    if (query.length < 2) {
        $('search-live-dot').classList.remove('live');
        meta.textContent = query.length === 0 ? 'Waiting for input…' : 'Keep typing (2+ characters)…';
        results.innerHTML = '<div class="empty-state"><div class="empty-emoji">⌨️</div><h3>Start typing</h3><p>Pick a user (or all) and type — results stream in as you type.</p></div>';
        $('search-more').classList.add('hidden');
        return;
    }

    try {
        const data = await api('/api/search', { query, author: state.searchAuthor, limit: 50 });
        if (seq !== state.searchSeq) return; // stale response
        $('search-live-dot').classList.remove('live');
        state.searchTotal = data.total;
        const who = state.searchAuthor === '__all__' ? 'all users' : state.searchAuthor;
        meta.innerHTML = `<span class="match-count">${fmtNum(data.total)}</span> match${data.total === 1 ? '' : 'es'} for "<b>${escapeHtml(query)}</b>" from ${escapeHtml(who)}`;

        results.innerHTML = '';
        if (!data.messages.length) {
            results.innerHTML = '<div class="empty-state"><div class="empty-emoji">🤷</div><h3>No matches</h3><p>Try a different phrase or user.</p></div>';
            $('search-more').classList.add('hidden');
            return;
        }
        appendSearchResults(data.messages, query);
        state.searchOffset = data.messages.length;
        $('search-more').classList.toggle('hidden', state.searchOffset >= data.total);
    } catch (e) {
        if (seq !== state.searchSeq) return;
        $('search-live-dot').classList.remove('live');
        meta.textContent = `Search failed: ${e.message}`;
    }
}

function appendSearchResults(messages, query) {
    const results = $('search-results');
    messages.forEach((msg, i) => {
        const card = document.createElement('div');
        card.className = 'result-card';
        card.style.animationDelay = `${Math.min(i * 20, 300)}ms`;
        card.innerHTML = `
            <div class="result-meta">
                <span class="result-author">${escapeHtml(msg.author)}</span>
                <span class="result-channel"># ${escapeHtml(msg.channel_name || '')}</span>
                <span class="result-time">${fmtTime(msg.timestamp)}</span>
            </div>
            <div class="result-content">${highlightHtml(msg.content, query)}</div>
            <div class="result-jump">↪ Click to view in context</div>`;
        card.addEventListener('click', () => jumpToMessage(msg.message_id));
        results.appendChild(card);
    });
}

async function loadMoreSearch() {
    const btn = $('search-more');
    btn.disabled = true;
    try {
        const data = await api('/api/search', {
            query: state.searchQuery, author: state.searchAuthor,
            limit: 50, offset: state.searchOffset,
        });
        appendSearchResults(data.messages, state.searchQuery);
        state.searchOffset += data.messages.length;
        btn.classList.toggle('hidden', state.searchOffset >= state.searchTotal);
    } catch (e) {
        console.error(e);
    } finally {
        btn.disabled = false;
    }
}

// ---------------------------------------------------------
// FUN FACTS MODE
// ---------------------------------------------------------
$('facts-user-select').addEventListener('change', () => {
    state.factsAuthor = $('facts-user-select').value;
    loadFunFacts();
});

async function loadFunFacts() {
    const container = $('facts-content');
    container.dataset.loaded = '1';
    container.innerHTML = '<div class="loading-spinner"><div class="spinner"></div></div>';
    try {
        const f = await api('/api/funfacts', { author: state.factsAuthor });
        renderFunFacts(f);
    } catch (e) {
        container.innerHTML = `<div class="empty-state"><p>Failed: ${escapeHtml(e.message)}</p></div>`;
    }
}

function barListHtml(items, { mono = true } = {}) {
    if (!items || !items.length) return '<p style="color: var(--text-muted); font-size: 13px;">Not enough data 🤷</p>';
    const max = items[0].count || 1;
    return items.map((it) => `
        <div class="bar-row">
            <span class="bar-label" title="${escapeHtml(it.value)}">${escapeHtml(it.value)}</span>
            <div class="bar-track"><div class="bar-fill" style="width:${Math.max(3, (it.count / max) * 100)}%"></div></div>
            <span class="bar-count">${fmtNum(it.count)}×</span>
        </div>`).join('');
}

function hourChartHtml(hist, peak) {
    const max = Math.max(1, ...Object.values(hist || {}));
    let bars = '';
    for (let h = 0; h < 24; h++) {
        const c = hist?.[h] || 0;
        const pct = Math.round((c / max) * 100);
        bars += `
            <div class="hour-bar-wrap${h === peak ? ' peak' : ''}" title="${h}:00 — ${fmtNum(c)} messages">
                <div class="hour-bar" style="height:${Math.max(2, pct)}%"></div>
                <span class="hour-label">${h % 6 === 0 ? h : ''}</span>
            </div>`;
    }
    return `<div class="hour-chart">${bars}</div>`;
}

