    const topTrigram = f.top_trigrams[0];
    const topLetter = f.top_letters[0];
    const topWord = f.top_words[0];

    container.innerHTML = `
        <div class="facts-hero">
            <div class="hero-stat">
                <div class="hero-stat-value">${fmtNum(f.message_count)}</div>
                <div class="hero-stat-label">Messages</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${fmtNum(f.total_words)}</div>
                <div class="hero-stat-label">Words typed</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${f.avg_words_per_message}</div>
                <div class="hero-stat-label">Avg words / msg</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${topLetter ? `"${escapeHtml(topLetter.value)}"` : '—'}</div>
                <div class="hero-stat-label">Favorite letter</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${topWord ? escapeHtml(topWord.value) : '—'}</div>
                <div class="hero-stat-label">Favorite word</div>
            </div>
            <div class="hero-stat">
                <div class="hero-stat-value">${f.busiest_hour !== null ? f.busiest_hour + ':00' : '—'}</div>
                <div class="hero-stat-label">Busiest hour</div>
            </div>
        </div>

        <div class="facts-grid">
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">👯</span> Top Bigrams ${topBigram ? `— "${escapeHtml(topBigram.value)}"` : ''}</div>
                ${barListHtml(f.top_bigrams)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🎰</span> Top Trigrams ${topTrigram ? `— "${escapeHtml(topTrigram.value)}"` : ''}</div>
                ${barListHtml(f.top_trigrams)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">📝</span> Top Words <small style="color:var(--text-muted); font-weight: 400;">(stopwords removed)</small></div>
                ${barListHtml(f.top_words)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🔤</span> Letter Frequency</div>
                ${barListHtml(f.top_letters)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">😀</span> Top Emoji</div>
                ${barListHtml(f.top_emoji)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🏠</span> Favorite Channels</div>
                ${barListHtml(f.favorite_channels)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🕐</span> Activity by Hour ${f.busiest_day ? `— peaks on ${escapeHtml(f.busiest_day)}s` : ''}</div>
                ${hourChartHtml(f.hour_histogram, f.busiest_hour)}
            </div>
            <div class="fact-card">
                <div class="fact-card-title"><span class="fact-emoji">🎭</span> Personality Stats</div>
                ${barListHtml([
                    { value: 'questions ?', count: f.question_messages },
                    { value: 'exclaims !', count: f.exclaim_messages },
                    { value: 'ALL CAPS', count: f.caps_messages },
                ].sort((a, b) => b.count - a.count))}
            </div>
            <div class="fact-card wide">
                <div class="fact-card-title"><span class="fact-emoji">📜</span> Longest Message Ever (${fmtNum(f.longest_message_length)} chars)</div>
                <div class="fact-blockquote">${escapeHtml(f.longest_message)}${f.longest_message_length > 500 ? '…' : ''}</div>
            </div>
        </div>`;
}

